const express = require('express');
const { Pool } = require('pg');

const pool = new Pool();
const router = express.Router();

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);
  const params = [limit + 1];
  let where = '';

  if (req.query.cursor) {
    try {
      const [createdAt, id] = JSON.parse(
        Buffer.from(String(req.query.cursor), 'base64url').toString()
      );
      params.push(createdAt, id);
      where = 'WHERE (created_at, id) < ($2::timestamptz, $3)';
    } catch {
      return res.status(400).json({ error: 'Invalid cursor' });
    }
  }

  try {
    // created_at::text keeps microseconds, which a JS Date would truncate.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params
    );

    const page = rows.slice(0, limit);
    const last = page[page.length - 1];
    const nextCursor =
      rows.length > limit
        ? Buffer.from(JSON.stringify([last.cursor_ts, last.id])).toString('base64url')
        : null;

    res.json({ data: page.map(({ cursor_ts, ...order }) => order), nextCursor });
  } catch (err) {
    // Class 22 is a data exception: the cursor decoded but held bad values.
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'Invalid cursor' });
    next(err);
  }
});

module.exports = router;
